INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:51','mayalex_normativos','01_PENAL','ENTREGA VIGILADA O CON- TROLADA. Consiste en permitir que remesas ilícitas o sospechosas de drogas, sustancias prohibidas o de sustancias por las que se hayan sustituido las antes mencionadas o dinero en efectivo, instrumentos u objetos de valor, armas, municiones, explosivos u otros instrumentos relacionados con el tipo de delito que se investiga, se entreguen, ingresen, transiten o salgan del territorio hondureño, con el conocimiento y bajo el control y supervisión permanente de las autoridades competentes, con el propósito de:

1) Identificar a las personas y organizaciones involucradas en la comisión del delito;
2) Identificar los bienes, producto, instrumentos o ganancias, para lograr su incautación y posterior comiso;
3) Obtener evidencias, elementos de prueba o información necesaria en la investigación; o,
4) Prestar auxilio a autoridades extranjeras con los mismos fines.','51','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":51,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"1ae8c1aafeac1bd6a25482002c4e015784f490d3cbfe08cc6745126373bfda3b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','51','1ae8c1aafeac1bd6a25482002c4e015784f490d3cbfe08cc6745126373bfda3b','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:52','mayalex_normativos','01_PENAL','AUTORIZACIÓN DE LA ENTREGA VIGILADA. A requerimiento del Ministerio Público, con el fin exclusivo de la investigación del delito que se trate, el Órgano Jurisdiccional Competente, mediante resolución fundada y bajo la más estricta reserva y confidencialidad, puede autorizar la utilización de la entrega vigilada.

Durante el desarrollo de una entrega vigilada o controlada, se autoriza asimismo el uso de todos los medios técnicos idóneos para documentar por fotografías, audio, vídeo o cualquier otro medio, el desarrollo y los resultados de la operación.

Para darle cumplimiento al presente Artículo, la autoridad competente puede aplazar o suspender la detención de las personas sospechosas de participar en la comisión del delito.','52','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":52,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"b7fe65c50a6c0fe767438709cee57f8a80e138ee945a00c844901b158f43cd3a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','52','b7fe65c50a6c0fe767438709cee57f8a80e138ee945a00c844901b158f43cd3a','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:53','mayalex_normativos','01_PENAL','EXENCIÓN DE RESPONSA- BILIDAD PENAL EN LA ENTREGA VIGILADA. Los funcionarios o empleados encargados de investigar el delito, que estén autorizados para participar en la ejecución de la entrega vigilada están exentos de responsabilidad penal, cuando con la finalidad de obtener elementos probatorios o con el fin de dar seguimiento del producto del delito, lleven a cabo actos que pudieran interpretarse como elementos de lavado de activos o cualquier otro delito.

No está permitida la provocación para la comisión de delitos.

No obstante lo anterior, los funcionarios o agentes de investigación son responsables, disciplinaria, administrativa, civil y penalmente por todos los actos que constituyan un injustificado o desproporcionado exceso o abuso en el cumplimiento de su misión.','53','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":53,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"9c35f71f0204fd9b3913ce3a1e00f742c5ad34dca1b5e01723e5c745ac12cce0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','53','9c35f71f0204fd9b3913ce3a1e00f742c5ad34dca1b5e01723e5c745ac12cce0','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:54','mayalex_normativos','01_PENAL','DEL AGENTE ENCUBIERTO. Con la finalidad de obtener evidencia, elementos de prueba o información que permita constatar la realización del delito, así como de impedir su consumación o de obtener la individualización o la detención de los autores, partícipes o encubridores para obtener y asegurar los elementos probatorios necesarios, durante el curso de la investigación, a requerimiento del Ministerio Público, el Órgano Jurisdiccional Competente, mediante resolución fundada y bajo la más estricta reserva y confidencialidad, puede autorizar que funcionarios, empleados o agentes encargados de aplicar la Ley, u otras personas cuando el caso lo requiera, asuma una identidad o función ficticia o encubierta, en forma temporal.

La finalidad del Agente Encubierto es introducirse como integrante de organizaciones delictivas que tengan entre sus fines la comisión del delito de lavado de activos, financiamiento del terrorismo u otro que esté siendo investigado, relacionado con estas materias.

A requerimiento del Ministerio Público, el Órgano Jurisdiccional Competente, mediante resolución fundada y bajo la más estricta reserva y confidencialidad, puede autorizar que funcionarios, empleados o agentes encargados de aplicar la Ley u otras personas cuando el caso lo requiera, asuman una identidad o función ficticia o encubierta, en forma temporal.

Durante el desarrollo de una operación encubierta, se autoriza asimismo la utilización todos los medios técnicos idóneos que permitan documentar por fotografía, audio, vídeo o cualquier otro medio, el desarrollo y los resultados de la operación.','54','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":54,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"0bfd53d3e68998643d83a624c8906c75fc9f89249cab65cd1893fca769f6d4dc","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','54','0bfd53d3e68998643d83a624c8906c75fc9f89249cab65cd1893fca769f6d4dc','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:55','mayalex_normativos','01_PENAL','REQUISITOS PARA EL AGENTE ENCUBIERTO. La designación de un funcionario como Agente Encubierto se debe realizar previo análisis detallado de riesgo de infiltración para determinar todos los requerimientos de orden técnico, logístico y profesional de la operación, en procura de garantizar la seguridad de los intervinientes y preservar la reserva de la investigación.

Toda operación del funcionario debe observar los protocolos de seguridad que establezcan los organismos de investigación y los equipos de investigación deben integrarse con el personal suficiente y los perfiles necesarios de acuerdo con el tipo de organización que es objeto de infiltración, procurando que siempre actúe un agente de contacto, con el fin de servir de enlace entre el funcionario y el ente de investigación, quien además debe participar en el proceso de garantía de autenticidad de las evidencias, elementos de prueba e información obtenidas en la operación.

La persona que deba actuar como Agente Encubierto, debe reunir los requisitos de idoneidad, siendo funcionarios calificados.','55','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":55,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"493bc4cc2bab4f3006dbcc326d42cd43a85d29f3ad7af10ad8724a99742d17da","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','55','493bc4cc2bab4f3006dbcc326d42cd43a85d29f3ad7af10ad8724a99742d17da','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:56','mayalex_normativos','01_PENAL','DESIGNACIÓN DEL AGENTE ENCUBIERTO. La designación del Agente Encubierto debe efectuarla el Órgano Jurisdiccional a propuesta del Ministerio Público.

En la designación del funcionario que actúe como agente encubierto, se debe consignar el nombre verdadero del agente y la identidad sustituida con la que debe actuar en el caso, la cual debe ser reservada fuera del expediente, sin constancia en el mismo y con las debidas medidas de confidencialidad.

La designación del agente encubierto debe mantenerse en estricto secreto.

En caso de revelación de la información a que se refiere el presente Artículo, el infractor incurre en el delito de Infidencia, tipificado en el Artículo 72 de la Ley Contra el Financiamiento del Terrorismo contenida en el Decreto No. 241-2010 de fecha 18 de Noviembre de 2010.','56','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":56,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"3cadc63b629cf0453f1105cf481aacb0f74d76027c4f6755c24caf6ad8fba3ed","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','56','3cadc63b629cf0453f1105cf481aacb0f74d76027c4f6755c24caf6ad8fba3ed','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:57','mayalex_normativos','01_PENAL','TRÁMITE DE LA INFORMACIÓN. La información que obtenga el funcionario que actúa como agente encubierto, se debe entregar al Ministerio Público y poner en conocimiento del Órgano Jurisdiccional que lo haya autorizado.

El Órgano Jurisdiccional Competente, el Ministerio Público o cualquier autoridad competente, debe realizar todas las diligencias para que en la incorporación de la información a la causa, no se evidencie de ninguna manera la actuación o identidad del agente encubierto.

Cuando las investigaciones hayan finalizado y sea imprescindible tener como prueba la información personal obtenida por el Agente Encubierto, éste puede ser citado a declarar debiendo otorgarse la garantía de protección para testigos establecida en el Código Procesal Penal y en la Ley de Protección a Testigos en Proceso en el Proceso Penal.','57','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":57,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"4d9c63edb817598c0066259a15af76de0d90ddfe5db2c468d96169befb0ea5f6","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','57','4d9c63edb817598c0066259a15af76de0d90ddfe5db2c468d96169befb0ea5f6','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:58','mayalex_normativos','01_PENAL','EXENCIÓN DE RESPONSA- BILIDAD PENAL PARA ELAGENTE ENCUBIERTO. Está exento de responsabilidad penal el funcionario que actúe como agente encubierto cuando como consecuencia de la actividad desarrollada, se hubiese visto compelido a incurrir en una figura tipificada en el Código Penal o en las leyes penales especiales, siempre que no implique poner en peligro inminente la vida o integridad física u ocasionar un grave sufrimiento físico o psicológico a otra persona, mientras tales actuaciones surjan en el contexto de la investigación encomendada. Está prohibida la provocación para la comisión de delitos.

No obstante lo anterior, los funcionarios o agentes de investigación son responsables disciplinaria, administrativa, civil y penalmente por todos los actos que constituyan un injustificado o desproporcionado exceso o abuso en el cumplimiento de su misión.

En caso que el funcionario que actúe como agente encubierto sea detenido en razón de la función que realiza, hará saber confidencialmente al Fiscal Actuante, quien en forma reservada debe recabar la información pertinente para verificar tales extremos. Si se comprobare su condición de agente encubierto, el Fiscal debe tomar las decisiones necesarias para dejar en libertad a la persona sin revelar su verdadera identidad.

Ninguna persona puede ser obligada a actuar como agente encubierto. La negativa a hacerlo no debe ser tenida como antecedente desfavorable para ningún efecto.','58','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":58,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"3ebca3f90a45d317a9d766b53f739abdc31b1f2808efa8695be0b8d662176683","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','58','3ebca3f90a45d317a9d766b53f739abdc31b1f2808efa8695be0b8d662176683','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:59','mayalex_normativos','01_PENAL','RESERVA DEL AGENTE ENCU- BIERTO. El Funcionario que actúe como Agente Encubierto no debe de revelar su condición a ninguna persona distinta del agente de contacto, ya sea durante se esté ejecutando la operación o después que haya finalizado su participación, salvo autorización del Ministerio Público.

En caso de contravención a este Artículo, el agente encubierto es responsable del delito de Infidencia, tipificado en el Artículo 72 de la Ley Contra el Financiamiento del Terrorismo contenida en el Decreto No. 241-2010 de fecha 18 de Noviembre de 2010.','59','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":59,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"8b6bd6d0d41f2f479e62bb6f47c6c6a1f74e25f6de70145fb5a03f9c60077d41","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','59','8b6bd6d0d41f2f479e62bb6f47c6c6a1f74e25f6de70145fb5a03f9c60077d41','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:60','mayalex_normativos','01_PENAL','AUTORIZACIÓN JUDICIAL. Las Técnicas Especiales de Investigación de Entrega Vigilada y Agente Encubierto, deben ser autorizadas por el Órgano Jurisdiccional Competente a solicitud del Ministerio Público.

Excepcionalmente y en casos de urgencia, el Ministerio Público puede autorizar la entrega vigilada dentro del territorio nacional y el Agente Encubierto, debiendo informar dentro del término de veinticuatro (24) horas al Órgano Jurisdiccional, quien convalidará o anulará lo actuado.

Para el uso del Informante no se requiere autorización Judicial.','60','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":60,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"594d52069624004c78429ec617ef4ab5b01989ca77f5658275976f7dfa5b42af","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','60','594d52069624004c78429ec617ef4ab5b01989ca77f5658275976f7dfa5b42af','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:61','mayalex_normativos','01_PENAL','INTERVENCIÓN DE COMUNICA- CIONES PRIVADAS. Para la ejecución de la Técnica Especial de Intervenciones Telefónicas Privadas, se debe efectuar conforme a lo dispuesto en la Ley Especial Sobre Intervención de las Comunicaciones Privadas, contenida en el Decreto Legislativo No. 243-2011 de fecha 8 de Diciembre de 2011.','61','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":61,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"87860e2176b835518ab09f9eeadda9104c15b0414b70a22b161cd1036503a13b","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','61','87860e2176b835518ab09f9eeadda9104c15b0414b70a22b161cd1036503a13b','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:62','mayalex_normativos','01_PENAL','TRÁMITE DE SOLICITUD EN PIEZA SEPARADA. Toda solicitud para la implementación de alguna de las Técnicas Especiales de Investigación, debe resolverse por el órgano jurisdiccional en pieza separada y reservada, misma que puede mantener esta calidad hasta la audiencia preliminar de la etapa intermedia del proceso penal o hasta la admisión por parte del Órgano Jurisdiccional de la solicitud de privación de dominio en la etapa judicial, a menos que la técnica especial de investigación aún no haya concluido, manteniéndose la reserva hasta tanto.

El acceso de la pieza separada que contenga el trámite judicial de la técnica especial de investigación no debe incluir la identidad del funcionario que actúe que agente encubierto y/o del informante, en los casos que se haya decretado su reserva como medida de protección personal.','62','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":62,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"465b03a5ad05662790f0e9728ad6eea27ff17dba1c09632e3b4d4668e3bd4127","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','62','465b03a5ad05662790f0e9728ad6eea27ff17dba1c09632e3b4d4668e3bd4127','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:63','mayalex_normativos','01_PENAL','EL COMISO. En caso de condena por cualquiera de los delitos previstos en esta Ley, se debe ordenar el decomiso de los activos o fondos utilizados o que se pretendía utilizar para cometerlos. Igualmente se debe ordenar el decomiso o comiso de los activos o fondos que sean objeto del delito, productos o instrumentos del mismo.','63','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":63,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"30c6c40c2e94b3484a7c63c5b800dfed1e7d3bfaa4aceb5e26941dca7652a9ad","ubicacion":["CAPÍTULO IX","DEL COMISO Y LAS MEDIDAS CAUTELARES O","DE ASEGURAMIENTO"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','63','30c6c40c2e94b3484a7c63c5b800dfed1e7d3bfaa4aceb5e26941dca7652a9ad','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:64','mayalex_normativos','01_PENAL','DERECHOS DEL AFECTADO. La persona que pretenda hacer valer algún derecho sobre los activos o fondos sobre los cuales recayó medida precautoria o cautelar o, sentencia definitiva donde se ordena el comiso o decomiso puede interponer los recursos legales correspondientes dentro de los plazos establecidos en el Código Procesal Penal.','64','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":64,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"85ae0a7a787881d64bd9c972a2861aebd47a0a16ffb0862fa9b62d3e0bf799df","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','64','85ae0a7a787881d64bd9c972a2861aebd47a0a16ffb0862fa9b62d3e0bf799df','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:65','mayalex_normativos','01_PENAL','PROCEDENCIA. Cuando el Órgano Jurisdiccional Competente o el Ministerio Público en su caso, tengan conocimiento de cualquiera de los hechos constitutivos del delito del lavado de activos, debe dictar sin dilación alguna, sin notificación, ni audiencias previas, la medida precautoria, cautelar o de aseguramiento pertinente, prevista en la Legislación Nacional, con la finalidad de preservar la disponibilidad de los activos, productos o instrumentos relacionados con el delito de lavado de activos.

Si la medida precautoria o cautelar es dictada por el Ministerio Público, lo pondrá en conocimiento del Órgano Jurisdiccional Competente, dentro del término de setenta y dos (72) horas siguientes, explicando las razones que lo determinaron. El Órgano Jurisdiccional Competente en auto motivado, convalidará o anulará total o parcialmente lo actuado.','65','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":65,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"7cbe2c968396d1445173a2f0c91304f26b0097201fda501b2e8a1d23afa9b7b7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','65','7cbe2c968396d1445173a2f0c91304f26b0097201fda501b2e8a1d23afa9b7b7','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:66','mayalex_normativos','01_PENAL','EJECUCIÓN DE LAS MEDIDAS CAUTELAR O ASEGURAMIENTO. Para efectos de su aplicación y eficacia, las medidas precautorias, cautelares o de aseguramiento que se dicten, se deben comunicar por cualquier medio legal a la Institución donde deba ejecutarse.

La autoridad competente debe remitir tal solicitud por escrito dentro de las veinticuatro (24) horas siguientes, cuando por la urgencia el requerimiento hubiese sido de manera distinta a la escrita.

Las instituciones obligadas a ejecutar la inscripción de las medidas, deben proceder inmediatamente a ejecutarlas en aquellos casos en que los bienes, empresas o sus titulares estuvieran plenamente identificados y en caso contrario previo a la identificación, deben llevar a cabo todas las medidas necesarias para asegurar la disponibilidad de los bienes, productos o instrumentos que obren a nombre de las personas descritas en la orden de aseguramiento.

En los registros de la propiedad inmueble y mercantil, así como en otras instituciones públicas o privadas que deban ejecutar las medidas, no se puede alegar prelación alguna para retrasar o no llevar a cabo la medida. Toda inscripción haciendo caso omiso a lo estipulado en este Artículo es nula y acarrea responsabilidad administrativa, penal y civil al infractor.

En el caso que la medida precautoria o cautelar, recaiga sobre productos financieros ésta se debe hacer efectiva por medio de las Unidades de Cumplimiento de las Instituciones Supervisadas, sin perjuicio de que se ejecuten a por medio de otros funcionarios de la misma.','66','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":66,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"bca3e5e456985e721efcde308ee0360c37fd6ca58f7ad477aab4c2a8e26208a7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','66','bca3e5e456985e721efcde308ee0360c37fd6ca58f7ad477aab4c2a8e26208a7','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:67','mayalex_normativos','01_PENAL','DESTINO DE LOS BIENES CON MEDIDA PRECAUTORIA. Si fuera sea necesaria la incautación de bienes, productos o instrumentos sobre los cuales recaiga medida precautoria, cautelar o de aseguramiento, el órgano competente debe proceder inmediatamente a ponerlos a disposición de la Oficina Administradora de Bienes Incautados (OABI), para su administración, guarda, custodia o destrucción en su caso.','67','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":67,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"ed37840907f25d62817953dc782d31aa7e828ed70836e0b7d551b5e52cba1f1f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','67','ed37840907f25d62817953dc782d31aa7e828ed70836e0b7d551b5e52cba1f1f','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:68','mayalex_normativos','01_PENAL','NOTIFICACION DE LAS MEDIDAS PRECAUTORIAS. Las medidas precautorias, cautelares o de aseguramiento, una vez ejecutadas, deben ser notificadas al afectado o a su apoderado legal, por cualquier medio legal, en caso de ser posible. En su defecto, la notificación se hará por medio de la publicación por una sola vez, en un diario de circulación nacional y en un medio de difusión con cobertura nacional.

El término señalado en el Artículo 76 para iniciar el proceso de declaratoria de abandono no comenzará a correr sino hasta el día siguiente después de la comunicación.','68','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":68,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"b192dd65fdb3fd7f856b6ac08272dc13accf6b6aeadab96825d3344b86634962","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','68','b192dd65fdb3fd7f856b6ac08272dc13accf6b6aeadab96825d3344b86634962','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:69','mayalex_normativos','01_PENAL','DURACIÓN DE LAS MEDIDAS DE ASEGURAMIENTO. La situación jurídica de los bienes se debe resolver en el menor tiempo posible, cuando se obtenga los elementos de juicio para ello, atendiendo al respeto de los derechos de legalidad, debido proceso y defensa y preservando las garantías inherentes al derecho de propiedad. Estas medidas no pueden durar más de veinticuatro (24) meses. Transcurrido el término anterior sin que el Ministerio Público haya ejercido la acción penal pública, éstas deben ser revocadas en el caso de no existir mérito para mantener la medida, a menos que los bienes se encuentren en alguna circunstancia o causal de privación definitiva del dominio de bienes de origen ilícito, evento en el cual, se debe ordenar promover el trámite correspondiente. El término indicado en este Artículo puede ser prorrogado mediante autorización judicial por un término de doce (12) meses por una sola vez y comenzará a contar a partir de la inscripción en el registro correspondiente.','69','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":69,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"5b93570a80af70ec537a9f56b0d1599110b9bb905a246a459aadbb6502103c5c","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','69','5b93570a80af70ec537a9f56b0d1599110b9bb905a246a459aadbb6502103c5c','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:70','mayalex_normativos','01_PENAL','CASOS DE REVOCACIÓN DE LAS MEDIDAS DE ASEGURAMIENTO. El Órgano Jurisdiccional Competente debe revocar las medidas precautorias, cautelares o de aseguramiento y devolver al reclamante los bienes, productos o instrumentos cuando concurra alguna de las circunstancias siguientes:

1) El reclamante pruebe el origen legal y su interés legítimo en los bienes, productos o instrumentos;
2) Al reclamante no se le debe imputar ningún tipo de participación con respecto al delito objeto del proceso;
3) El reclamante desconocía, sin que haya habido negligencia, el uso ilegal de bienes, productos o instrumentos o cuando teniendo conocimiento, no consintió de modo voluntario en usarlos ilegalmente;
4) El reclamante no haya adquirido derecho alguno sobre los bienes, productos o instrumentos de la persona procesada en circunstancias que conducían razonablemente a establecer que el derecho sobre aquellos le habría sido transferido para efectos de evitar la práctica de medidas precautorias o el comiso;

5) El reclamante hizo todo lo necesario para impedir el uso ilegal de los bienes, productos o instrumentos; y,
6) Una vez vencido el plazo de la duración de la medida de aseguramiento.El Órgano Jurisdiccional Competente solamente puede revocar las medidas precautorias, cautelares o de aseguramiento, si la petición la formula el Ministerio Público como ente encargado de la investigación.

El Órgano Jurisdiccional Competente también puede revocar las medidas precautorias, cautelares o de aseguramiento en la sentencia, sin perjuicio de lo dispuesto en el Artículo 11 de la Ley Sobre Privación Definitiva del Dominio de Bienes de Origen Ilícito, contenida en el Decreto No. 27-2010 del 18 de Noviembre de 2010, la misma no puede ejecutarse debido a que sobre los activos recayó sentencia declarativa de privación de dominio en otro proceso.','70','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":70,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"4639fb01cd37175b326d44dd2ba7444ab42f6da16274d3788f6f9f4f49a2a091","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','70','4639fb01cd37175b326d44dd2ba7444ab42f6da16274d3788f6f9f4f49a2a091','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:71','mayalex_normativos','01_PENAL','NULIDAD DE CONTRATOS. Será nulo todo contrato contenido en un instrumento público o privado o en cualquier otro documento, otorgado a título gratuito u oneroso, entre vivos o por causa de muerte, cuyo fin sea poner bienes fuera del alcance de la aplicación de las medidas cautelares o de aseguramiento o que se dicte el comiso o decomiso a que hace referencia esta Ley.

La nulidad debe ser declarada por el órgano jurisdiccional que esté conociendo la causa penal en la sentencia que se emita una vez concluido el proceso. En caso de nulidad de un contrato a título oneroso, el precio sólo debe ser restituido al comprador en la medida en que haya sido efectivamente pagado y que el contrato haya sido celebrado de buena fe por parte de éste.

Contra la resolución que decrete la nulidad puede interponerse los recursos de reposición y apelación en un solo efecto.','71','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":71,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"250744b1d7bb9ee9d8ff02a0f94a7173582caaddd7a84a63b4d6092f81249d53","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','71','250744b1d7bb9ee9d8ff02a0f94a7173582caaddd7a84a63b4d6092f81249d53','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:72','mayalex_normativos','01_PENAL','BIENES EQUIVALENTES. Cuando no sea posible la localización, identificación o afectación material de los bienes investigados o la pretensión de comiso o decomiso resulte improcedente por el reconocimiento de los derechos de un tercero de buena fe, el Órgano Jurisdiccional Competente debe ordenar el comiso de los activos hasta un valor equivalente al de los bienes que no se puedan afectar.

Lo dispuesto en el párrafo anterior no se debe interpretar en perjuicio de terceros de buena fe exentos de responsabilidad.','72','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":72,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"cb5b7a19c7205f57648bc7000c72adff6099ad20a94d15114424e36f7bd494be","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','72','cb5b7a19c7205f57648bc7000c72adff6099ad20a94d15114424e36f7bd494be','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:73','mayalex_normativos','01_PENAL','OFICINA ADMINISTRADORA DE BIENES INCAUTADOS (OABI). La Oficina Administradora de Bienes Incautados (OABI), es un Órgano adscrito a la Secretaría de Estado en el Despacho de la Presidencia, con personalidad jurídica propia, goza de autonomía técnica, administrativa y financiera para la gestión directa de los asuntos que por Ley se le encomienden; constituyéndose como un órgano técnico especializado para la adecuada guarda, custodia y administración de los bienes incautados, decomisados o abandonados, que la autoridad competente ponga a su disposición.

Para la guarda y administración de los activos en dinero a que se refiere el párrafo anterior, la Organización Administradora de Bienes Incautados (OABI) debe hacer los depósitos en cuentas especiales que para tal efecto se abran en cualquier institución del Sistema Financiero Nacional o en el Banco Central de Honduras (BCH), de acuerdo al Reglamento de Administración de Bienes Incautados y Decomisados y Reglamento de Inversiones que apruebe previamente el Presidente de la República, a propuesta de la Comisión Interinstitucional para la Prevención del Lavado de Activos y Financiamiento del Terrorismo (CIPLAFT), en el que se deben observar los requisitos de seguridad y rentabilidad. En el caso de los bienes muebles, éstos deben ser depositados en almacenes generales de depósito o en las instalaciones de las Fuerzas Armadas de Honduras destinadas al efecto cuando el caso así lo requiera.','73','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":73,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"d7387f0d5504a874be60c4ea09bd6910e61f72f498a036f0bb130c8e94df62ac","ubicacion":["CAPÍTULO X","DE LA ADMINISTRACIÓN DE LOS BIENES","INCAUTADOS O DECOMISADOS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','73','d7387f0d5504a874be60c4ea09bd6910e61f72f498a036f0bb130c8e94df62ac','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:74','mayalex_normativos','01_PENAL','USO PROVISIONAL DE BIENES ADMINISTRADOS. En los casos de bienes, productos, instrumentos o ganancias, que estén siendo administrados por la Organización Administradora de Bienes Incautados (OABI) y no se haya dictado sentencia definitiva o resolución que defina su situación jurídica, ésta previa autorización de la Secretaría de Estado en el Despacho de la Presidencia o del Consejo Nacional de Defensa y Seguridad (CNDS) cuando se sometiere a su instancia tal extremo, debe aprobar la suscripción de los convenios de uso provisional de los bienes incautados.

La Organización Administradora de Bienes Incautados (OABI) en cumplimiento a los Convenios correspondientes, debe asignar los bienes en uso provisional siempre y cuando con la debida antelación se presente la documentación que acredite el contrato de seguro contra daños, incendio u otros siniestros.

El seguro debe tener la finalidad de garantizar el resarcimiento por deterioro o destrucción, cuando las características y el valor del bien así lo ameriten.

Los gastos en que se incurra por la contratación de la póliza de seguros, mantenimiento, funcionamiento y otros deben ser pagados por la institución u organismo a quien se le asignen; a efectos de cual deben tomarse las previsiones presupuestarias en cada ejercicio fiscal para el cumplimiento de esta disposición.

El procedimiento que ha de seguirse para la asignación y su cumplimiento está sujeto al Reglamento de Administración de Bienes Incautados y Decomisados.

La autorización o entrega de uso provisional sin llenar los requisitos da lugar a la aplicación de sanciones civiles, administrativas o penales.','74','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":74,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"7a6a72f1eb0f201cdd63a2f8651b9a91739658e920ed1541416768d08439e5d0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','74','7a6a72f1eb0f201cdd63a2f8651b9a91739658e920ed1541416768d08439e5d0','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:75','mayalex_normativos','01_PENAL','BIENES SUCEPTIBLES DE DETERIORO O DE COSTOSA ADMINISTRACIÓN. Cuando la medida precautoria o cautelar recaiga sobre bienes que corran riesgo de perecer, perderse, depreciarse, desvalorizarse, que su administración entrañe perjuicio, costo desproporcionado para el Estado al momento de devolverlo en su caso o que se proyecten inservibles cuando se dicte la sentencia de mérito, estos previo autorización de la Secretaría de Estado en el Despacho de la Presidencia y/o Consejo Nacional de Defensa y Seguridad (CNDS) pueden ser enajenados, subastados o vendidos anticipadamente por la Organización Administradora de Bienes Incautados (OABI) pretendiendo mantener la productividad de los mismos. Lo mismo procede cuando se trate de semovientes u otros animales. Todo lo anterior sin perjuicio del avalúo correspondiente que al efecto debe realizar la Dirección

General de Bienes Nacionales o cualquier otra entidad competente dependiendo del bien a subastar.

Si llevada a cabo la audiencia de venta o subasta, no se presentare ofertas o por cualquier otra circunstancia no se realizare esta, la Organización Administradora de Bienes Incautados (OABI) se debe donar el producto a una institución de beneficencia de carácter público y organizaciones de desarrollo social sin fines de lucro. El Reglamento de Administración de Bienes Incautados o Decomisados, que debe ser emitido por el Presidente de la República, regulará lo relativo a la subasta, venta o donación establecida en este Artículo. De todo lo actuado se debe informar al Juez Competente y al Ministerio Público.

El producto de la subasta o venta anticipada se debe depositar en el fondo especial de dinero incautado.','75','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":75,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"3711dffd9080ff79679cad694c112be3ad5b30a55d67eca03e5803186a1340d1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','75','3711dffd9080ff79679cad694c112be3ad5b30a55d67eca03e5803186a1340d1','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:76','mayalex_normativos','01_PENAL','BIENES ABANDONADOS. Trans- curridos treinta (30) días a partir de la notificación a que se refiere el Artículo 68 de esta Ley, sin que ninguna persona haya reclamado su devolución acreditando ser su propietaria, la Organización Administradora de Bienes Incautados (OABI) con la aprobación del Órgano Jurisdiccional Competente, debe publicar por una sola vez en un diario escrito de circulación nacional el aviso de la incautación de dichos bienes, con la advertencia de que si dentro del término de treinta (30) días no se presentare persona alguna reclamando su devolución acreditando ser su propietario o poseedor legítimo, la autoridad competente los declarar en situación de abandono.

Declarado el abandono, la Organización Administradora de Bienes Incautados (OABI) debe proceder de oficio a realizar la distribución de acuerdo al Artículo 78 reformado de la Ley Sobre Privación Definitiva del Dominio de Bienes de Origen Ilícito, contenida en el Decreto No. 27-2010 del 18 de Noviembre de 2010.

En caso que la persona se presente dentro de los términos dispuestos en este Artículo al proceso y acredite ser la propietaria del bien, se debe continuar con el desarrollo del mismo por parte de la autoridad competente.','76','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":76,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"090e8e25a84df39547f1ca1deafd47f453eb0b8498f5d3c959acea1175756ca0","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','76','090e8e25a84df39547f1ca1deafd47f453eb0b8498f5d3c959acea1175756ca0','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:77','mayalex_normativos','01_PENAL','DEVOLUCIÓN DE LOS BIENES. La Organización Administradora de Bienes Incautados (OABI), previa sentencia o resolución del Órgano Jurisdiccional Competente o del Ministerio Público, en su caso, en donde se ordene su devolución, debe cumplirla y ejecutarla, procediendo a la devolución de los activos, productos o instrumentos que se encuentren bajo su guarda, custodia o administración, en igual estado en que se encontraban al momento de la intervención, salvo aquellos deterioros ocurridos por el paso del tiempo o que no sean imputables a la Organización Administradora de Bienes Incautados (OABI).

En el caso de dinero en efectivo, la devolución comprende el principal más los intereses calculados a la tasa promedio de captación del Sistema Financiero Nacional registrada por el Banco Central de Honduras (BCH) en el mes anterior a la devolución, los intereses generados adicionales a esta tasa quedan a favor de la Organización Administradora de Bienes Incautados (OABI) como porcentaje de gastos de administración.','77','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":77,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"6ebfcd7db4276b7407210a05b9e011f397343854c0cd16618beb1a9084947ef4","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','77','6ebfcd7db4276b7407210a05b9e011f397343854c0cd16618beb1a9084947ef4','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:78','mayalex_normativos','01_PENAL','DISTRIBUCIÓN DE LOS BIENES DECLARADOS EN COMISO. Finalizado el proceso penal, cuando la sentencia ordene la pena de comiso, para efectos de distribución se debe proceder conforme a lo establecido en el Artículo 78 reformado de la Ley Sobre Privación Definitiva del Dominio de Bienes de Origen Ilícito, contenida en el Decreto No. 27-2010 de fecha 18 de Noviembre de 2010.','78','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":78,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"c2ee24554fe0d052a1cb7824907dff3a12cb8fa1a95395a50acf18cd5af8bc33","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','78','c2ee24554fe0d052a1cb7824907dff3a12cb8fa1a95395a50acf18cd5af8bc33','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:79','mayalex_normativos','01_PENAL','COOPERACIÓN ENTRE AUTORI- DADES. Las autoridades de Honduras, cuando se reúnan los requisitos, deben cooperar en la mayor medida posible con las autoridades de los demás países, en lo que concierne al intercambio de información para la investigación y enjuiciamiento del delito de lavado de activos, delito de testaferrato, así como en lo referente a la identificación de activos sobre los cuales puedan recaer medidas cautelares o de aseguramiento, el comiso o decomiso, a los fines de extradición, de la asistencia judicial recíproca o de cualquier otro tipo de cooperación permitida por la legislación nacional.','79','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":79,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"24204813935e16f267acc9505377ab15e7b44d49cd218e4f5bde23b4445d2f28","ubicacion":["CAPÍTULO XI","COOPERACIÓN INTERNACIONAL"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','79','24204813935e16f267acc9505377ab15e7b44d49cd218e4f5bde23b4445d2f28','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:80','mayalex_normativos','01_PENAL','SOLICITUDES DE MEDIDAS CAUTELARES O DE ASEGURAMIENTO. A solicitud de un Estado Extranjero, el Órgano Jurisdiccional Competente puede ordenar, de acuerdo con la Ley Interna, medidas cautelares o de aseguramiento sobre activos, productos o instrumentos situados en su jurisdicción que estuviesen relacionados con la Comisión del Delito de Lavado de Activos o de cualquiera de los delitos señalados en la presente Ley y de delitos precedentes, que se hayan cometido en el Estado Requirente; se debe aplicar lo dispuesto en las Convenciones Internacionales en la materia suscritas y ratificadas por Honduras y, que hayan sido invocadas.','80','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":80,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"1fe51059bd569de3f2e6d097ebca377edd9b9f897110b0ae8f162f6bc9a5617e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','80','1fe51059bd569de3f2e6d097ebca377edd9b9f897110b0ae8f162f6bc9a5617e','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:81','mayalex_normativos','01_PENAL','FACULTAD DE SOLICITAR Y PROPORCIONAR ASISTENCIA INTERNACIONAL. Los Órganos Jurisdiccionales Competentes, el Ministerio Público, El Banco Central de Honduras (BCH), la Comisión Nacional de Bancos y Seguros (CNBS) y las demás autoridades competentes, deben cooperar con sus homólogos de otros países, tomando medidas apropiadas, a efectos de solicitar y brindar asistencia en materia relacionada con la prevención, investigación y enjuiciamiento del delito de lavado de activos y otros delitos relacionados, de acuerdo con la presente Ley, Memorándums de Entendimiento, las Convenciones, Tratados y Acuerdos suscritos y ratificados por Honduras, de acuerdo a los límites de sus atribuciones y en base al principio de reciprocidad.

Las solicitudes se deben tramitar por medio de la autoridad central y se deben sujetar a los requisitos que establece la Convención, Convenio o Acuerdo que se invoque. En situaciones de urgencia la solicitud puede ser realizada por cualquier medio, pero debe ser confirmada por escrito siguiendo los procedimientos establecidos. De esta misma forma debe brindarse la respuesta a la petición.','81','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":81,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"4b30b9319dbb451747fadfa5a5a2159a2bcb7502336c1119f28d02a192a5f5fd","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','81','4b30b9319dbb451747fadfa5a5a2159a2bcb7502336c1119f28d02a192a5f5fd','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:82','mayalex_normativos','01_PENAL','DILIGENCIAS QUE SE PUEDEN SOLICITAR. Las diligencias que pueden solicitarse o proporcionarse a las autoridades competentes de otros países, por medio de asistencia judicial recíproca relativa a los delitos tipificados en esta Ley y otras aplicables, debe incluir en particular lo siguiente:

1) Recopilar elementos probatorios o tomar declaraciones a personas;

2) Prestar asistencia para poner a disposición de las autoridades judiciales del Estado Solicitante a las personas detenidas, a los testigos voluntarios y a otras personas para que presten declaraciones o ayuden en la realización de las investigaciones;
3) Notificar documentos judiciales;
4) Presentar documentos;
5) Realizar allanamientos;
6) Realizar inspecciones o incautaciones;
7) Examinar objetos y lugares;
8) Facilitar información, elementos probatorios e informes periciales;
9) Entregar originales o copias certificadas de documentos y expedientes relacionados con el caso e inclusive documentación gubernamental, bancaria, financiera, corporativa, de negocios o comercial;
10) Identificar, detectar y localizar activos con el fin de incautarlos y/o declararlos en comiso;
11) Ejecutar medidas precautorias, cautelares o de aseguramiento; y,
12) Cualquier otra forma de asistencia judicial, recíproca, autorizada por el Derecho, que no entre en conflicto con las leyes internas de Honduras o del país requerido.','82','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":82,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"37c0e4045fbed853a6358b29b20cf6e5ce1033543f3d7efc972cc8a3b121af25","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','82','37c0e4045fbed853a6358b29b20cf6e5ce1033543f3d7efc972cc8a3b121af25','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:83','mayalex_normativos','01_PENAL','MOTIVOS PARA DENEGAR ASISTENCIA JUDICIAL INTERNACIONAL. Las solicitudes de asistencia judicial pueden ser denegadas si no proceden de una autoridad competente, según la legislación del país requirente, que no hayan suscrito tratados y convenios con Honduras o conforme al procedimiento establecido en las leyes.','83','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":83,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"38589ceeea8dd5ab21baefa8a61c0c4282e030e6a19a3007f60c37878569eed7","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','83','38589ceeea8dd5ab21baefa8a61c0c4282e030e6a19a3007f60c37878569eed7','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:84','mayalex_normativos','01_PENAL','ASISTENCIA ADMINISTRATIVA. El Ministerio Público o cualquier otra autoridad competente, puede solicitar y proporcionar asistencia administrativa a las autoridades competentes de otros países, con el fin de facilitar la investigación y enjuiciamiento del delito de lavado de activos, testaferrato y otros aplicables, así como la identificación de los activos, productos o instrumentos derivados de los delitos señalados en la presente Ley y demás aplicables. Esta forma de obtención de elementos probatorios tiene validez en el proceso penal.','84','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":84,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"dca2f2c7225512ec8fb583cd97c0ec0cb9bca3c71e7a86545f12dfe27ab3fbb1","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','84','dca2f2c7225512ec8fb583cd97c0ec0cb9bca3c71e7a86545f12dfe27ab3fbb1','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:85','mayalex_normativos','01_PENAL','Dentro del término de (12) meses contados a partir del día siguiente de la entrada en vigencia de la presente Ley, sin que se haya resuelto la situación jurídica de los bienes sobre los cuales se ha dictado medida cautelar o de aseguramiento bajo el amparo del Decreto No.45-2002 de fecha 7 de Marzo de 2002; éstas deben de ser revocadas de oficio, a menos que los bienes se encuentren en alguna circunstancia o causal de privación definitiva del dominio de bienes de origen ilícito, evento en el cual, se debe ordenar promover el trámite correspondiente de conformidad con lo dispuesto en el Artículo 25 de la Ley de Privación Definitiva de Bienes de Origen Ilícito.','85','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":85,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"ec572748867ca6edfe9cc7407732a8292e694f381b27d526e9498959fe57445b","ubicacion":["CAPÍTULO XII","DISPOSICIONES FINALES Y TRANSITORIAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','85','ec572748867ca6edfe9cc7407732a8292e694f381b27d526e9498959fe57445b','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:86','mayalex_normativos','01_PENAL','FIJACIÓN DE MONTOS.- El Banco Central de Honduras (BCH) queda autorizado para fijar el monto de las sumas de dinero en efectivo o cualquier otro instrumento monetario para los efectos de los Artículos 8, 2, y 3 de esta Ley.','86','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":86,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"d520f490a2bc7cb332aba77d5f60cc356e7c1f1ae1efd0401fd5135fbff04ddf","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','86','d520f490a2bc7cb332aba77d5f60cc356e7c1f1ae1efd0401fd5135fbff04ddf','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:87','mayalex_normativos','01_PENAL','RESERVA Y CONFIDENCIALIDAD. Los funcionarios y empleados de la Unidad de Inteligencia Financiera (UIF), están obligados a guardar la reserva o confidencialidad de la información conocida en razón de su cargo. Esta reserva es obligatoria que se mantenga durante el ejercicio del cargo y después que hayan cesado en éste, por haber sido trasladado a otra sección o por haberse retirado de la institución. La reserva y confidencialidad es obligatoria para los funcionarios y empleados de la Comisión Nacional de Bancos y Seguros (CNBS) que por razón de la función que desempeñan tengan acceso a la información relacionada con delitos de Lavado de Activos y Financiamiento de Terrorismo.

Lo dispuesto respecto a la reserva y confidencialidad es aplicable a funcionarios y empleados del Ministerio Público y funcionarios y empleados de la Comisión Nacional de Bancos y Seguros (CNBS), responsables de la regulación de Actividades y Profesiones No Financieras Designadas (APNFD).

Es obligatoria la reserva y confidencialidad respecto a la institución o personas naturales que no tengan la condición de Sujetos Obligados a las cuales se les requiera información. Esta disposición, no es aplicable cuando se trate de la publicación de la sentencia o de la resolución en que se dictan medidas cautelares o de aseguramiento.

El incumplimiento de lo dispuesto en este Artículo da lugar a incurrir en delito de infidencia, tipificado en el Artículo 77 de la Ley Contra el Financiamiento del Terrorismo, contenido en el Decreto No.241-2010 de fecha 18 de Noviembre de 2010.

La reserva y confidencialidad comprende la prohibición de no relevar información sometida a reserva y confidencialidad sobre los asuntos de conocimiento de la Unidad de Inteligencia Financiera (UIF) relacionadas con las investigaciones, reportes y otros, a personas que pretendiendo hacerse valer de su posición jerárquica quieran conocer de las actuaciones con otra finalidad distinta a esta Ley o a cualquier otra persona que no tenga ningún tipo de relación funcional con las labores de análisis, cumplimiento y operaciones financieras que conoce la Unidad de Inteligencia Financiera (UIF).

El párrafo anterior incluye realizar requerimientos si no hay un sustento legal para hacerlo.','87','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":87,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"7cd2265f804063147df47364b383d689eda90c8d162dddef291c8fbbc037783e","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','87','7cd2265f804063147df47364b383d689eda90c8d162dddef291c8fbbc037783e','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:88','mayalex_normativos','01_PENAL','Reformar el Artículo 78 de la Ley Sobre Privación Definitiva del Dominio de Bienes de Origen Ilícito, contenido en el Decreto 27-2010 de fecha 5 de Mayo de 2010, el que en adelante debe leerse así:

“ARTÍCULO 78. DISTRIBUCIÓN Y DESTINACIÓN DE BIENES DECLARADOS EN COMISO. Una vez firme la sentencia que declare la privación definitiva del dominio o el decomiso de los bienes, productos, instrumentos o ganancias, la Organización Administradora de Bienes Incautados (OABI) previo resolución del Consejo Nacional de Defensa y Seguridad (CNDS), debe proceder a la distribución del dinero en efectivo, títulos valores y productos financieros, más los rendimientos, utilidades o intereses que se encuentren a su disposición por haber sido incautados, así como el que se hubiere depositado como producto de la subasta de bienes, ventas anticipadas y otros. La distribución se debe hacer siguiendo las reglas siguientes:

1) Cuarenta y Cinco por ciento (45%) para las unidades, dependencias, programas o proyectos que directamente trabajen en el Sector Seguridad y Justicia, con énfasis en las unidades de investigación;
2) Cuarenta y Cinco por ciento (45%) para las unidades, dependencias, programas o proyectos que directamente trabajen en el Sector Prevención; el Gabinete de Prevención a través de su coordinación puede autorizar directamente a la Oficina Administradora de Bienes Incautados (OABI), el financiamiento de programas o proyectos afines hasta por un monto de QUINIENTOS MIL LEMPIRAS (L. 500,000.00); y,
3) Diez por ciento (10%) para la Organización Administradora de Bienes Incautados (OABI) en apoyo y como complemento del presupuesto para su operación, mantenimiento y cumplimiento de sus obligaciones legales.

Los fondos asignados mediante la distribución arriba descrita no pueden ser destinados a gastos corrientes como ser pago de deudas, salarios, aumentos salariales, alquileres de inmuebles, eventos protocolarios o sociales, artículos de lujo o suntuosos u otros similares; pues deben ser destinados únicamente a la inversión en el fortalecimiento de las capacidades y competencias propias de cada unidad o dependencia según el caso y, deben emplearse para los destinos específicos enunciados en el numeral del correspondiente beneficiario.

No obstante lo dispuesto en el párrafo anterior, las instituciones beneficiarias deben presentar y justificar previamente ante la Oficina Administradora de Bienes Incautados (OABI), para su correspondiente aprobación, la planificación y el programa de inversión de dichos recursos previo a efectuar la transferencia a su favor. Queda facultada la Oficina Administradora de Bienes Incautados (OABI) para aprobar inversiones o empleo de estos recursos en casos no previstos expresamente en este Artículo o, en su caso, denegar la transferencia de fondos cuando no corresponda a los destinos e inversiones a los cuales deben ser dirigidos los mismos de conformidad al presente Artículo.

Se prohíbe de manera expresa que estos recursos sean utilizados con fines distintos a los enunciados en el párrafo que antecede. La contravención a estas disposiciones da lugar a responsabilidades admitida, civil y penal.”','88','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":88,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"666d0e6adce774a9d938580c53233d06df717ea6e4965f64df1a22654532d813","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','88','666d0e6adce774a9d938580c53233d06df717ea6e4965f64df1a22654532d813','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:89','mayalex_normativos','01_PENAL','ESPECIALIDAD DE LA LEY. Esta Ley tiene preeminencia sobre cualquier otra que le contraríe o se le oponga y constituye una excepción a la regla general establecida en los Artículos 956 y 1058 del Código de Comercio y, 39 de la Ley del Impuesto Sobre la Renta.','89','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":89,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"a3c7d43890e500a7bb4aa6fbc8bac1d84ea3c14478343717adb46e8338c5731a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','89','a3c7d43890e500a7bb4aa6fbc8bac1d84ea3c14478343717adb46e8338c5731a','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:90','mayalex_normativos','01_PENAL','ASEGURAMIENTO DE BIENES. Todos los bienes sobre los que se decrete medida precautoria, de aseguramiento, cautelar o incautación por el Ministerio Público o la Autoridad Judicial competente en procesos relacionados a delitos de criminalidad organizada, deben ponerse, según aplique conforme a la Ley, a disposición de la Oficina Administradora de Bienes Incautados (OABI) para su debida, guarda, custodia y administración; para lo cual la Oficina Administradora de Bienes Incautados (OABI) debe aplicar obligatoriamente lo dispuesto en esta la Ley, Ley Sobre Privación Definitiva del Dominio de Bienes de Origen Ilícito, Ley Contra Financiamiento del Terrorismo y demás reglamentos aplicables en lo que respecta a la Administración de los Bienes Incautados.','90','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":90,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"27af693f1e064502f2b8c6a73a31224c1e20fc059625610679721a8dadf4a02d","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','90','27af693f1e064502f2b8c6a73a31224c1e20fc059625610679721a8dadf4a02d','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:91','mayalex_normativos','01_PENAL','REGLAMENTOS. La Comisión Nacional de Bancos y Seguros (CNBS) debe reglamentar dentro de los primeros ciento veinte (120) días siguientes a partir de la vigencia de la presente Ley, el régimen, obligaciones, medidas de control y otros deberes acerca de las obligaciones impuestas a las Instituciones Supervisadas.

La Comisión Interinstitucional de Justicia Penal, dentro de los ciento veinte días (120) días siguientes a partir de la vigencia de la presente Ley, debe reglamentar lo relativo a las Técnicas Especiales de Investigación.','91','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":91,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"bb7e72cd139f2cc9809f4ae93dd9a47a2f04b9a511533e3d29498ebd7ade4a6f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','91','bb7e72cd139f2cc9809f4ae93dd9a47a2f04b9a511533e3d29498ebd7ade4a6f','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:92','mayalex_normativos','01_PENAL','DEROGATORIAS. Derogar la Ley Especial Sobre el Abandono de Vehículos Automotores, contenida en el Decreto No. 245-2002 de fecha 17 de Julio de 2002 y publicado en el Diario Oficial “La Gaceta”, en fecha 5 de Septiembre de 2002, así como Ley Contra el Delito de Lavado de Activos, contenida en el Decreto No.45-2002 de fecha 5 de Marzo de 2002, publicada en el Diario Oficial “La Gaceta” el 15 de Mayo de 2002.','92','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":92,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"0e96779f7922a7391806af8db85d23d82b53bede00b7a8c60d9a941c6da8277f","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','92','0e96779f7922a7391806af8db85d23d82b53bede00b7a8c60d9a941c6da8277f','OLA12_LA_2015_01',now()),
('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:93','mayalex_normativos','01_PENAL','VIGENCIA. El presente Decreto entrará en vigencia treinta (30) días después de la fecha de su publicación en el Diario Oficial “La Gaceta”.','93','Ley Especial contra el Lavado de Activos de Honduras (Decreto No. 144-2014)','{"norm_id":"HN:LEY_LAVADO_ACTIVOS","instrumento_id":"LEY_LAVADO_ACTIVOS","ingest_batch":"OLA12_LA_2015_01","ola":"OLA12","ordinal":93,"decreto":"144-2014","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"La Gaceta No. 33,718 del 30 de abril de 2015 (PDF nativo, recopilación «LEY-APNFDS-Y-LAVADO-DE-ACTIVOS-HONDURAS.pdf», págs. 9–22 y 63–74), Sección A, págs. A.9–A.34: Decreto No. 144-2014, extraído columna por columna.","pdf_sha256":"27416d092eb571a18ce45536be6e89fa075542b36fd18ba3fee243ce0efb4f00","article_sha256":"5ddaee32b0113f25c6f2b4d57cc2dc0aa2cf95455824d9ddc27a44861099a126","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_LAVADO_ACTIVOS','93','5ddaee32b0113f25c6f2b4d57cc2dc0aa2cf95455824d9ddc27a44861099a126','OLA12_LA_2015_01',now())
